REVOKE ALL ON FUNCTION public.fn_close_managed_game(text,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_close_managed_game(text,uuid) TO "postgres";
