REVOKE ALL ON FUNCTION public.fn_spin_reserve_row_requires_exact_journal() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_spin_reserve_row_requires_exact_journal() TO "postgres";
