REVOKE ALL ON FUNCTION public.fn_satellite_transfer_ledger_is_immutable() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_satellite_transfer_ledger_is_immutable() TO "postgres";
