REVOKE ALL ON FUNCTION public.fn_table_seats_lightning_anchor_guard() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_table_seats_lightning_anchor_guard() TO "postgres";
