REVOKE ALL ON FUNCTION public.fn_terminal_tournament_seat_is_immutable() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_terminal_tournament_seat_is_immutable() TO "postgres";
