REVOKE ALL ON FUNCTION public.trg_lock_and_classify_tournament_table() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.trg_lock_and_classify_tournament_table() TO "postgres";
