REVOKE ALL ON FUNCTION public.trg_lock_tournament_player_launch_proof() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.trg_lock_tournament_player_launch_proof() TO "postgres";
