REVOKE ALL ON FUNCTION public.fn_ca_normalize_new_mtt_capacity() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_ca_normalize_new_mtt_capacity() TO "postgres";
DO $$ BEGIN IF md5(pg_get_functiondef('public.fn_ca_normalize_new_mtt_capacity()'::regprocedure)) IS DISTINCT FROM '06cbd73a8011fac92e0c51b8d752b3da' THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_SOURCE_CHANGED: %','public.fn_ca_normalize_new_mtt_capacity()'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.fn_cancelled_tournament_parent_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=OLD.id) THEN
    RAISE EXCEPTION 'receipted cancellation % is immutable',OLD.id
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;
