REVOKE ALL ON FUNCTION public.fn_guard_tournament_completing_claim() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_guard_tournament_completing_claim() TO "postgres";
