REVOKE ALL ON FUNCTION public.fn_terminal_wallet_transaction_is_immutable() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_terminal_wallet_transaction_is_immutable() TO "postgres";
