REVOKE ALL ON FUNCTION public.trg_freeze_registered_tournament_settlement_contract() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.trg_freeze_registered_tournament_settlement_contract() TO "postgres";
