REVOKE ALL ON FUNCTION public.trg_tournament_atomic_place_completion_guard() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.trg_tournament_atomic_place_completion_guard() TO "postgres";
GRANT EXECUTE ON FUNCTION public.trg_tournament_atomic_place_completion_guard() TO "service_role";
