REVOKE ALL ON FUNCTION public.guard_wallet_balance_write() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.guard_wallet_balance_write() TO "postgres";
GRANT EXECUTE ON FUNCTION public.guard_wallet_balance_write() TO "service_role";
