REVOKE ALL ON FUNCTION public.fn_ca_tournament_place_amounts(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_ca_tournament_place_amounts(uuid) TO "postgres";
