CREATE OR REPLACE FUNCTION public.fn_ca_record_tournament_accounting_credit(p_key text, p_tournament uuid, p_user uuid, p_amount numeric, p_ledger uuid, p_wallet uuid, p_payout uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_l jsonb;v_w jsonb;v_payout jsonb;v_p jsonb;v_t jsonb;v_entries uuid[];
BEGIN
 SELECT to_jsonb(l) INTO v_l FROM public.chip_ledger l WHERE id=p_ledger;
 SELECT to_jsonb(w) INTO v_w FROM public.wallet_transactions w WHERE id=p_wallet;
 SELECT to_jsonb(p) INTO v_payout FROM public.tournament_payouts p WHERE id=p_payout;
 SELECT to_jsonb(t) INTO v_t FROM public.tournaments t WHERE id=p_tournament;
 SELECT to_jsonb(p) INTO v_p FROM public.tournament_players p WHERE tournament_id=p_tournament AND user_id=p_user;
 SELECT COALESCE(array_agg(id ORDER BY observed_at,id),'{}'::uuid[]) INTO v_entries
 FROM public.tournament_participant_funding_receipts WHERE registration_id=(v_p->>'id')::uuid;
 IF v_l IS NULL OR v_w IS NULL OR v_t IS NULL
    OR v_l->>'tournament_id' IS DISTINCT FROM p_tournament::text
    OR v_l->>'from_type' IS DISTINCT FROM 'prize_liability'
    OR v_l->>'from_entity_id' IS DISTINCT FROM p_tournament::text
    OR v_l->>'to_type' IS DISTINCT FROM 'player_wallet'
    OR v_l->>'to_entity_id' IS DISTINCT FROM p_user::text
    OR v_l->>'club_id' IS NULL OR (v_l->>'amount')::numeric IS DISTINCT FROM p_amount
    OR v_w->>'user_id' IS DISTINCT FROM p_user::text
    OR v_w->>'related_entity_id' IS DISTINCT FROM p_tournament::text
    OR v_w->>'type' IS DISTINCT FROM 'credit' OR (v_w->>'amount')::numeric IS DISTINCT FROM p_amount
    OR (p_payout IS NOT NULL AND (v_payout IS NULL
       OR v_payout->>'idempotency_key' IS DISTINCT FROM p_key
       OR v_payout->>'user_id' IS DISTINCT FROM p_user::text
       OR v_payout->>'tournament_id' IS DISTINCT FROM p_tournament::text
       OR (v_payout->>'amount')::numeric IS DISTINCT FROM p_amount))
    OR NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency WHERE key=p_key AND user_id=p_user AND amount=p_amount) THEN
   RAISE EXCEPTION 'Original tournament credit references do not match' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.tournament_accounting_credit_receipts(
 idempotency_key,tournament_id,user_id,asset,amount,ledger_id,wallet_transaction_id,payout_id,
 credited_club_id,ledger_snapshot,wallet_snapshot,payout_snapshot,registration_snapshot,tournament_snapshot,entry_receipt_ids)
 VALUES(p_key,p_tournament,p_user,'chips',p_amount,p_ledger,p_wallet,p_payout,
 (v_l->>'club_id')::uuid,v_l,v_w,v_payout,v_p,v_t,v_entries);
END $function$;
ALTER FUNCTION public.fn_ca_record_tournament_accounting_credit(text,uuid,uuid,numeric,uuid,uuid,uuid) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_record_tournament_accounting_credit(text,uuid,uuid,numeric,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_ca_record_tournament_accounting_credit(text,uuid,uuid,numeric,uuid,uuid,uuid) TO "postgres";
DO $$ BEGIN IF md5(pg_get_functiondef('public.fn_ca_record_tournament_accounting_credit(text,uuid,uuid,numeric,uuid,uuid,uuid)'::regprocedure)) IS DISTINCT FROM 'cb13485c0ff8bdc787d0c6aff9f22c37' THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_SOURCE_CHANGED: %','public.fn_ca_record_tournament_accounting_credit(text,uuid,uuid,numeric,uuid,uuid,uuid)'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.fn_credit_player_wallet_once(p_user_id uuid, p_amount numeric, p_idempotency_key text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_inserted integer; v_tourn uuid; v_club uuid; v_balance numeric;
  v_is_tournament boolean := false; v_has_any_club boolean;
  v_fallback uuid;
BEGIN
    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO wallet_credit_idempotency (key, user_id, amount)
        VALUES (p_idempotency_key, p_user_id, p_amount)
        ON CONFLICT (key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        -- FALSE, not void: the caller needs to know it must NOT write a
        -- ledger row for a credit somebody else already made.
        IF v_inserted = 0 THEN RETURN false; END IF;
    END IF;

    IF p_idempotency_key IS NOT NULL AND p_idempotency_key LIKE 'tourney:%' THEN
      v_is_tournament := true;
      BEGIN
        v_tourn := (split_part(p_idempotency_key, ':', 2))::uuid;
      EXCEPTION WHEN OTHERS THEN v_tourn := NULL;
      END;
      IF v_tourn IS NOT NULL THEN
        SELECT tp.club_id INTO v_club FROM tournament_players tp
         WHERE tp.tournament_id = v_tourn AND tp.user_id = p_user_id LIMIT 1;
        IF v_club IS NULL THEN
          SELECT t.club_id INTO v_club FROM tournaments t WHERE t.id = v_tourn;
          v_club := COALESCE(public.fn_player_home_club(p_user_id, NULL), v_club);
        END IF;
      END IF;
    END IF;

    IF v_club IS NULL THEN
      v_club := public.fn_player_home_club(p_user_id, NULL);
    END IF;

    IF v_club IS NOT NULL THEN
      PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);
      UPDATE club_members
         SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = NOW()
       WHERE user_id = p_user_id AND club_id = v_club
       RETURNING chip_balance INTO v_balance;
      IF v_balance IS NOT NULL THEN RETURN true; END IF;
    END IF;

    /* ZERO-DRIFT (2026-08-31): cross-club tournament entry - the stamped club
       holds no wallet for this player. Follow the money home instead of
       refusing a prize the pool already owes. */
    IF v_is_tournament AND v_tourn IS NOT NULL THEN
      SELECT ct.club_id INTO v_fallback
        FROM chip_transactions ct
        JOIN tournaments t ON t.id = v_tourn
       WHERE ct.from_user_id = p_user_id
         AND ct.transaction_type = 'tournament_buyin'
         AND ct.notes = 'Tournament buy-in: ' || t.name
         AND ct.created_at > COALESCE(t.started_at, t.created_at, now()) - interval '7 days'
         AND EXISTS (SELECT 1 FROM club_members m
                      WHERE m.user_id = p_user_id AND m.club_id = ct.club_id)
       ORDER BY ct.created_at DESC LIMIT 1;
      IF v_fallback IS NULL THEN
        v_fallback := public.fn_player_home_club(p_user_id, NULL);
      END IF;
      IF v_fallback IS NULL THEN
        SELECT m.club_id INTO v_fallback
          FROM club_members m
         WHERE m.user_id = p_user_id
           AND COALESCE(m.status, 'active') IN ('active','approved')
         ORDER BY COALESCE(m.chip_balance, 0) DESC, m.club_id LIMIT 1;
      END IF;
      IF v_fallback IS NOT NULL AND v_fallback IS DISTINCT FROM v_club THEN
        PERFORM public.fn_ensure_club_wallet(p_user_id, v_fallback);
        UPDATE club_members
           SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = NOW()
         WHERE user_id = p_user_id AND club_id = v_fallback
         RETURNING chip_balance INTO v_balance;
        IF v_balance IS NOT NULL THEN RETURN true; END IF;
      END IF;
    END IF;

    SELECT EXISTS (SELECT 1 FROM club_members m WHERE m.user_id = p_user_id)
      INTO v_has_any_club;

    IF v_is_tournament OR v_has_any_club THEN
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('critical','credit_player_wallet',
              'Club Arena credit could not resolve a club wallet - payment refused rather than pooled',
              jsonb_build_object('user_id',p_user_id,'amount',p_amount,
                                 'idempotency_key',p_idempotency_key,'tournament_id',v_tourn));
      RAISE EXCEPTION 'No club wallet resolves for Club Arena credit to player %', p_user_id;
    END IF;

    UPDATE wallets SET balance = balance + p_amount, updated_at = NOW()
      WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
    IF NOT FOUND THEN
        INSERT INTO wallets (user_id, wallet_type, balance, locked_balance, created_at, updated_at)
        VALUES (p_user_id, 'PLAYER', p_amount, 0, NOW(), NOW());
    END IF;

    RETURN true;
END;
$function$;
