REVOKE ALL ON FUNCTION public.fn_credit_player_wallet_once(uuid,numeric,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_credit_player_wallet_once(uuid,numeric,text) TO "postgres";
