REVOKE ALL ON FUNCTION public.fn_ca_legacy_spin_original_fee_proof(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_ca_legacy_spin_original_fee_proof(uuid) TO "postgres";
