REVOKE ALL ON FUNCTION public.fn_tournament_payouts_are_append_only() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_tournament_payouts_are_append_only() TO "postgres";
