DO $$ BEGIN IF md5(pg_get_functiondef('public.fn_serialize_engine_maintenance_break_write()'::regprocedure)) IS DISTINCT FROM '6d62a5f9ad5e8fa615e3eac9396266a3' THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_SOURCE_CHANGED: %','public.fn_serialize_engine_maintenance_break_write()'; END IF; END $$;
