CREATE OR REPLACE FUNCTION public.fn_ca_capture_hand_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(OLD.rake_amount, 0) > 0 OR COALESCE(OLD.bbj_amount, 0) > 0
     OR OLD.reported IS TRUE THEN
    INSERT INTO public.ca_hand_financial_facts
      (hand_id, table_id, tournament_id, hand_number, big_blind, pot_size,
       rake_amount, bbj_amount, winners, hand_created_at)
    VALUES (OLD.id, OLD.table_id, OLD.tournament_id, OLD.hand_number, OLD.big_blind,
            OLD.pot_size, OLD.rake_amount, OLD.bbj_amount, OLD.winners, OLD.created_at)
    ON CONFLICT (hand_id) DO NOTHING;
  END IF;
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
  -- never block a prune; count the miss
  BEGIN
    INSERT INTO public.ca_ledger_write_failures (source_table, message, sqlstate)
    VALUES ('ca_hand_financial_facts', left(SQLERRM, 500), SQLSTATE);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN OLD;
END $function$;
