GRANT EXECUTE ON FUNCTION public.fn_settle_tournament_rake(uuid,text) TO "service_role";
DO $$ BEGIN IF md5(pg_get_functiondef('public.fn_settle_tournament_rake(uuid,text)'::regprocedure)) IS DISTINCT FROM '5e76e51907b0e966fb22e7535eec478d' THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_SOURCE_CHANGED: %','public.fn_settle_tournament_rake(uuid,text)'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.fn_tournament_finish_kind(p_tournament_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches d
       WHERE d.tournament_id = p_tournament_id
    ) THEN 'final_table_deal'
    WHEN lower(COALESCE(t.variant,'')) = 'satellite'
      OR upper(COALESCE(t.tournament_type,'')) = 'SATELLITE'
      OR t.satellite_target_id IS NOT NULL THEN 'satellite'
    ELSE 'normal'
  END
  FROM public.tournaments t
  WHERE t.id = p_tournament_id;
$function$;
